function clockText(){let h=Math.floor(state.minute/60)%24,m=Math.floor(state.minute%60);return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`}
function calendarText(){return ['MON','TUE','WED','THU','FRI','SAT','SUN'][(state.day-1)%7]+' · DAY '+String(state.day).padStart(2,'0')+' · '+['SPRING','SUMMER','AUTUMN','WINTER'][Math.floor((state.day-1)/28)%4]}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function percentBar(id,v){const el=$('#'+id);el.style.width=clamp(v,0,100)+'%';el.className='fill'+(v<22?' bad':v<43?' warn':'')}
function paintUI(){$('#time').textContent=clockText();$('#date').textContent=calendarText();$('#energyText').textContent=Math.round(state.energy)+'%';$('#wellText').textContent=Math.round(state.well)+'%';$('#hungerText').textContent=Math.round(state.hunger)+'%';percentBar('energyBar',state.energy);percentBar('wellBar',state.well);percentBar('hungerBar',state.hunger);$('#cash').textContent='$'+Math.floor(state.cash).toLocaleString();$('#jobText').textContent=state.job;$('#rep').textContent=state.rep>55?'Well liked':state.rep>20?'Known face':state.rep< -15?'Distrusted':'Neutral';$('#friends').textContent=state.friends+' close';$('#mood').textContent=state.mood>68?'Hopeful':state.mood>45?'Steady':'Uneasy';$('#jobs').textContent=state.market>68?'Growing':state.market<35?'Tight':'Stable';$('#weather').textContent=state.weather;$('#pulseText').textContent=state.market<35?'The job market is tightening; small businesses are watching every dollar.':state.mood>68?'The district feels open to possibility this morning.':'People are settling into the day at their own pace.'}
function save(){const data={...state,npcs:npcs.map(n=>({x:n.x,z:n.z,trust:n.trust,mood:n.mood,energy:n.energy,cash:n.cash,memories:n.memories}))};localStorage.setItem('reality-unbound-save',JSON.stringify(data));state.lastSaved=Date.now();toast('World saved · your story will be here when you return.')}
function load(){try{const d=JSON.parse(localStorage.getItem('reality-unbound-save')||'null');if(!d)return;Object.assign(state,d);state.story=d.story||[];if(d.npcs)for(let i=0;i<Math.min(npcs.length,d.npcs.length);i++){const n=npcs[i],v=d.npcs[i];Object.assign(n,v);n.group.position.set(n.x,0,n.z);n.targetX=n.x;n.targetZ=n.z}event('You return to a district that kept moving.')}catch(e){console.warn('Save could not be loaded',e)}}
load();if(!state.story.length)event('A new chapter begins in Harbor District.');paintUI();

