function openDialog(title,tag,description,options){dialogOpen=true;const el=$('#dialog');el.innerHTML=`<button class="close" id="closeDialog">×</button><div class="eyebrow">${tag}</div><h3>${title}</h3><p>${description}</p><div class="choices">${options.map((o,i)=>`<button class="choice" data-choice="${i}">${o.title}<span>${o.sub||''}</span></button>`).join('')}</div>`;el.classList.add('show');$('#closeDialog').onclick=closeDialog;el.querySelectorAll('.choice').forEach((b,i)=>b.onclick=()=>{const fn=options[i].run;closeDialog();fn()})}
function closeDialog(){dialogOpen=false;activeNpc=null;$('#dialog').classList.remove('show')}
function advance(hours=0,minutes=0){state.minute+=hours*60+minutes;while(state.minute>=1440){state.minute-=1440;state.day++;onNewDay()}paintUI()}
function onNewDay(){event(`Day ${state.day} begins. The district’s routines start again.`);if(state.day%7===0){state.cash-=680;if(state.cash<0){state.well=clamp(state.well-9,0,100);event('Rent is overdue. A note was slipped beneath your door.')}else event('Rent paid · $680. Home remains yours.')}if(state.day%28===0){$('#playerName').nextElementSibling.textContent='AGE '+(++state.age||27);event('Another year has passed. Time is yours to shape.')}}
function npcTalk(n){const greet=n.trust>12?'You pick up where you left off.':'You introduce yourself to';openDialog(n.name,n.role.toUpperCase(),`${greet} ${n.name.split(' ')[0]}. ${n.bio} ${n.memories.length?`They remember: “${n.memories[n.memories.length-1]}”`:''}`,[
{title:'Ask how they’re really doing',sub:'Listen first · build trust',run:()=>social(n,8,'You listened while they talked about life.')},
{title:'Share a little about yourself',sub:'Be open · build a genuine connection',run:()=>social(n,10,'You shared an honest moment together.')},
{title:'Ask what the neighborhood needs',sub:'Learn about the district',run:()=>{social(n,5,'You traded thoughts about Harbor District.');state.mood=clamp(state.mood+1,0,100);toast(n.name.split(' ')[0]+': “People could use a place to slow down.”')}}])}
function social(n,amount,memory){const like=(n.mood>70?1.2:.88);n.trust=clamp(n.trust+amount*like,0,100);n.mood=clamp(n.mood+5,0,100);n.memories.push(memory);n.memories=n.memories.slice(-5);state.well=clamp(state.well+2,0,100);state.rep=clamp(state.rep+2, -100,100);if(n.trust>=25&&!n.isFriend){n.isFriend=true;state.friends++;event(`${n.name.split(' ')[0]} is beginning to feel like a friend.`);toast('A new connection is taking root.')}else toast(`${n.name.split(' ')[0]} appreciates the conversation.`);paintUI()}
function interactPlace(p){let opts=[];if(p.id==='home')opts=[
{title:'Get a proper night’s sleep',sub:'Restore energy · spend 8 hours · hunger rises',run:()=>{state.energy=clamp(state.energy+48,0,100);state.well=clamp(state.well+5,0,100);state.hunger=clamp(state.hunger+10,0,100);advance(8);event('You slept through the night and woke to a new day.');toast('Rested. A clearer head, a slower morning.')}},
{title:'Take a quiet moment',sub:'Recover a little wellbeing · 30 minutes',run:()=>{state.well=clamp(state.well+8,0,100);state.energy=clamp(state.energy+3,0,100);advance(0,30);event('A quiet half-hour at home helped you reset.');toast('You made a little room to breathe.')}}];
else if(p.id==='cafe')opts=[{title:'Order coffee & a warm breakfast',sub:'−$14 · hunger −34 · wellbeing +5',run:()=>{if(state.cash<14)return toast('Not enough in your account for breakfast.');state.cash-=14;state.hunger=clamp(state.hunger-34,0,100);state.well=clamp(state.well+5,0,100);state.energy=clamp(state.energy+9,0,100);advance(0,25);event('You shared a quiet breakfast at Daybreak Café.');toast('Good coffee. The city feels a little more manageable.')}},{title:'Pick up a café shift',sub:'Earn $62 · energy −18 · hunger +12',run:()=>{state.cash+=62;state.energy=clamp(state.energy-18,0,100);state.hunger=clamp(state.hunger+12,0,100);state.job='Café regular · part-time';advance(3);state.rep+=2;event('You covered a busy café shift. The owner remembered your name.');toast('Shift complete · $62 earned.')}}];
else if(p.id==='studio')opts=[{title:state.job.includes('Between')?'Ask about regular work':'Work a focused shift',sub:'Earn $76 · develop a working routine',run:()=>{state.cash+=76;state.energy=clamp(state.energy-24,0,100);state.hunger=clamp(state.hunger+13,0,100);state.job=state.job.includes('Between')?'Harbor Works · junior associate':'Harbor Works · associate';state.rep=clamp(state.rep+3,-100,100);state.fitness=clamp(state.fitness+1,0,100);advance(4);event('You spent the afternoon at Harbor Works. A few new doors might open.');toast('A day’s work · $76 added to your balance.')}},{title:'Take a community skills class',sub:'−$20 · learn something useful · 2 hours',run:()=>{if(state.cash<20)return toast('You need $20 for the class materials.');state.cash-=20;state.well=clamp(state.well+3,0,100);state.rep=clamp(state.rep+2,-100,100);advance(2);event('You learned practical skills alongside people from the district.');toast('New skills, new possibilities.')}}];
