function distance(x1,z1,x2,z2){return Math.hypot(x1-x2,z1-z2)}
function getTarget(){let best=null,bestScore=.62;for(const p of places){const dx=p.x-state.x,dz=p.z-state.z,d=Math.hypot(dx,dz);if(d>4.8)continue;const dot=(dx*(-Math.sin(state.yaw))+dz*(-Math.cos(state.yaw)))/Math.max(d,.001);if(dot>bestScore){best={type:'place',item:p,distance:d};bestScore=dot}}for(const n of npcs){const dx=n.x-state.x,dz=n.z-state.z,d=Math.hypot(dx,dz);if(d>3.5)continue;const dot=(dx*(-Math.sin(state.yaw))+dz*(-Math.cos(state.yaw)))/Math.max(d,.001);if(dot>bestScore){best={type:'npc',item:n,distance:d};bestScore=dot}}return best}
function interact(){if(dialogOpen)return;if(!moved){toast('Step into your day to begin.');return}const target=getTarget();if(!target){toast('Nothing close enough to interact with.');return}if(target.type==='npc')npcTalk(target.item);else interactPlace(target.item)}
function begin(){if(!moved){moved=true;$('#help').classList.remove('show');event('You stepped out into a new day.')}renderer.domElement.requestPointerLock?.()}
$('#beginBtn').addEventListener('click',begin);$('#helpBtn').addEventListener('click',()=>{$('#help').classList.toggle('show');if($('#help').classList.contains('show'))document.exitPointerLock?.()});$('#saveBtn').addEventListener('click',save);$('#dialog').addEventListener('click',e=>{if(e.target.id==='dialog')closeDialog()});
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement!==renderer.domElement&&moved&&!dialogOpen){} });
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement&&!dialogOpen){state.yaw-=e.movementX*.0022;state.pitch=clamp(state.pitch-e.movementY*.0018,-1.15,1.15)}});
renderer.domElement.addEventListener('click',()=>{if(moved&&!dialogOpen&&document.pointerLockElement!==renderer.domElement&&innerWidth>720)renderer.domElement.requestPointerLock?.()});
document.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyE'){interact();return}if(e.code==='KeyH'){ $('#help').classList.toggle('show');document.exitPointerLock?.();return}if(e.code==='Escape'&&dialogOpen){closeDialog();return}keys.add(e.code)});
document.addEventListener('keyup',e=>keys.delete(e.code));
for(const b of document.querySelectorAll('.mobile button')){const key=b.dataset.key.toUpperCase();b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add('Key'+key);b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys.delete('Key'+key))}
let touchStart=null;renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')touchStart={x:e.clientX,y:e.clientY}});renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerType==='touch'&&touchStart&&moved){state.yaw-=(e.clientX-touchStart.x)*.006;state.pitch=clamp(state.pitch-(e.clientY-touchStart.y)*.004,-1.15,1.15);touchStart={x:e.clientX,y:e.clientY}}});renderer.domElement.addEventListener('pointerup',e=>{if(e.pointerType==='touch'&&touchStart){const delta=Math.hypot(e.clientX-touchStart.x,e.clientY-touchStart.y);if(delta<12&&moved&&!dialogOpen)interact();touchStart=null}});
function collision(nx,nz){if(Math.abs(nx)>111||Math.abs(nz)>111)return true;for(const b of buildings){const x=b.position.x,z=b.position.z;const base=b.children[0];const w=base.geometry.parameters.width/2+.65,d=base.geometry.parameters.depth/2+.65;if(Math.abs(nx-x)<w&&Math.abs(nz-z)<d)return true}for(const p of places){if(p.id==='park')continue;if(Math.abs(nx-p.x)<5.4&&Math.abs(nz-p.z)<4.4)return true}return false}
function movePlayer(dt){if(!moved||dialogOpen)return;let f=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),s=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0);if(!f&&!s)return;const len=Math.hypot(f,s)||1;f/=len;s/=len;const pace=keys.has('ShiftLeft')||keys.has('ShiftRight')?7.2:4.15;const dx=(-Math.sin(state.yaw)*f+Math.cos(state.yaw)*s)*pace*dt,dz=(-Math.cos(state.yaw)*f-Math.sin(state.yaw)*s)*pace*dt;let nx=state.x+dx,nz=state.z+dz;if(!collision(nx,state.z))state.x=nx;if(!collision(state.x,nz))state.z=nz;state.energy=clamp(state.energy-dt*(f&&pace>6?1.1:.25),0,100);camera.position.set(state.x,1.66,state.z)}
function routineTarget(n){const hour=state.minute/60;if(hour<7||hour>22){n.targetX=(n.id%3-1)*3;n.targetZ=4+(n.id%4)}else if(n.id%4===0){n.targetX=places[1].x+(n.id%3-1)*2;n.targetZ=places[1].z+6}else if(n.id%4===1){n.targetX=places[4].x+(n.id%3-1)*2;n.targetZ=places[4].z+7}else if(n.id%4===2){n.targetX=places[2].x+(n.id%3-1)*2;n.targetZ=places[2].z+7}else{n.targetX=places[5].x+(n.id%3-1)*3;n.targetZ=places[5].z+3}}
function simNPCs(dt,now){for(const n of npcs){n.energy=clamp(n.energy-dt*.3,8,100);if(now>n.nextRoutine){routineTarget(n);n.nextRoutine=now+8000+(n.id%5)*1700}const dx=n.targetX-n.x,dz=n.targetZ-n.z,d=Math.hypot(dx,dz);if(d>.3){const step=Math.min(d,n.speed*dt);let nx=n.x+dx/d*step,nz=n.z+dz/d*step;if(!collision(nx,nz)){n.x=nx;n.z=nz}else{n.targetX=n.x+(Math.random()-.5)*8;n.targetZ=n.z+(Math.random()-.5)*8}n.group.rotation.y=Math.atan2(dx,dz);n.legs.forEach((leg,i)=>leg.rotation.x=Math.sin(now*.009+n.phase+i*Math.PI)*.45)}else n.legs.forEach(leg=>leg.rotation.x=0);n.group.position.set(n.x,Math.abs(Math.sin(now*.003+n.phase))*.025,n.z);if(n.energy<20&&Math.random()<dt*.015)n.mood=clamp(n.mood-1,0,100)}for(const c of cars){c.g.position.x+=c.speed*dt;if(c.g.position.x>112)c.g.position.x=-112}}
function slowWorld(dt){if(!moved)return;state.minute+=dt*.32;while(state.minute>=1440){state.minute-=1440;state.day++;onNewDay()}state.hunger=clamp(state.hunger+dt*.11,0,100);state.well=clamp(state.well-(state.hunger>85?dt*.15:dt*.012),0,100);state.mood=clamp(state.mood+(Math.random()-.5)*dt*.035,25,90);state.market=clamp(state.market+(Math.random()-.5)*dt*.018,20,90);if(Math.random()<dt*.0014){const changes=['A new mural appeared by the ferry stop.','The café is looking for someone to cover weekend mornings.','A small rain shower left the streets shining.','Neighbors organized a book swap at Pier Gardens.','The market has fresh peaches from a nearby farm.','A late bus made for a longer commute across town.'];event(changes[Math.floor(Math.random()*changes.length)])}if(Math.random()<dt*.00045){state.market=clamp(state.market+(Math.random()-.5)*9,20,90);state.mood=clamp(state.mood+(Math.random()-.5)*8,20,90);event(state.market<40?'Harbor Works paused hiring as a few local contracts dried up.':'A new waterfront contract has brought a little optimism to the district.')}paintUI()}
function updateHints(){nearest=getTarget();const hint=$('#hint');if(nearest&&!dialogOpen){hint.innerHTML=`<span class="key">E</span> ${nearest.type==='npc'?'Talk with '+nearest.item.name:nearest.item.name} <span style="color:#9eaca3">· ${nearest.item.kind||nearest.item.role}</span>`;hint.classList.add('show')}else hint.classList.remove('show')}
function updateCamera(){camera.position.set(state.x,1.66,state.z);camera.rotation.order='YXZ';camera.rotation.y=state.yaw;camera.rotation.x=state.pitch}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-lastTick)/1000);lastTick=now;movePlayer(dt);if(now-lastNpcTick>120){simNPCs(dt*2,now);lastNpcTick=now}slowWorld(dt);updateCamera();if(Math.floor(now/150)!==Math.floor((now-dt*1000)/150))updateHints();renderer.render(scene,camera)}
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});
requestAnimationFrame(frame);
</script></body></html>

