.ui{position:fixed;inset:0;pointer-events:none}
.brand,.clock,.card,.hint,.toast,.help,.reticle{background:var(--glass);border:1px solid var(--line);backdrop-filter:blur(16px);box-shadow:0 12px 40px #0002}
.help{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(440px,calc(100vw - 32px));padding:24px;border-radius:17px;display:none;pointer-events:auto}
.help.show{display:block}
.help h2{margin:6px 0 10px;font-size:23px}
.help p{font-size:13px;color:#c2cec5;line-height:1.65}
.helpgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:17px 0}
.helpgrid div{background:#ffffff09;padding:10px;border-radius:8px;font-size:11px;color:#cbd6ce}
.helpgrid b{color:var(--mint);font:11px 'DM Mono',monospace}
.dialog{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(390px,calc(100vw - 32px));padding:20px;border-radius:15px;display:none;pointer-events:auto}
.dialog.show{display:block}
.dialog h3{margin:6px 0;font-size:20px}
.dialog p{font-size:12px;line-height:1.55;color:#c5d1c8}
.choices{display:grid;gap:7px;margin-top:14px}
.choice{width:100%;text-align:left;background:#ffffff0b;border:1px solid var(--line);color:#eff5ed;padding:11px;border-radius:8px;cursor:pointer;font:12px 'DM Sans'}
.choice:hover{border-color:var(--mint);background:#b8f07814}
.choice span{display:block;color:var(--muted);font-size:10px;margin-top:3px}

